def verify_screenshots(pages: list[dict]) -> None:
    shots = sorted((SCREENSHOTS_DIR / screenshot_filename(page["url"])).relative_to(ROOT) for page in pages)
    missing = [str(path) for path in shots if not (ROOT / path).exists()]
    invalid = []
    for path in shots:
        data = (ROOT / path).read_bytes()
        if data[:8] != b"\x89PNG\r\n\x1a\n" or len(data) <= 3000:
            invalid.append(str(path))
    if missing:
        raise RuntimeError(f"截图数量与成功页面数不一致，缺少: {missing}")
    if invalid:
        raise RuntimeError(f"截图无效或过小: {invalid}")
    print(f"  核对通过: {len(pages)} 个成功页面 ↔ {len(shots)} 张有效 PNG 截图")


def main() -> int:
    entry = read_entry_url()
    print(f"入口: {entry}")
    origin = urllib.parse.urlsplit(entry)
    print(f"仅爬取同源: {origin.scheme}://{origin.netloc}")

    server_proc: subprocess.Popen | None = None
    try:
        if wait_for_server(entry, timeout=0.3):
            print("检测到本地服务器已在运行，直接使用。")
        else:
            print("启动本地服务器: python3 serve.py")
            server_proc = subprocess.Popen(
                [sys.executable, "serve.py"],
                cwd=ROOT,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            if not wait_for_server(entry):
                return 2

        pages, broken_links = crawl(entry)
        print(f"爬取完成: {len(pages)} 个成功页面，{len(broken_links)} 条坏链")
        if broken_links:
            for broken in broken_links:
                print(f"  [broken] {broken['url']} -> {broken['status']}")

        screenshots = make_screenshots(pages)
        for page, relative in zip(pages, screenshots):
            page["screenshot"] = relative

        write_json(pages, broken_links)
        write_html(pages, broken_links)
        verify_screenshots(pages)
        print(f"已写入: {SITEMAP_JSON.name} 和 {SITEMAP_HTML.name}")
        print("完成。")
        return 0
    finally:
        if server_proc is not None:
            server_proc.terminate()
            try:
                server_proc.wait(timeout=5)
            except subprocess.TimeoutExpired:
                server_proc.kill()
                server_proc.wait(timeout=5)


if __name__ == "__main__":
    raise SystemExit(main())
