            parsed.scheme,
            f"{parsed.hostname}:{parsed.port}"
            if parsed.port and not ((parsed.scheme == "http" and parsed.port == 80) or (parsed.scheme == "https" and parsed.port == 443))
            else parsed.netloc,
            path,
            parsed.params,
            parsed.query,
            "",
        )
    )


def same_origin(url: str, origin: urllib.parse.SplitResult) -> bool:
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme not in ("http", "https"):
        return False
    expected_port = origin.port
    if expected_port is None:
        expected_port = 443 if origin.scheme == "https" else 80
    actual_port = parsed.port
    if actual_port is None:
        actual_port = 443 if parsed.scheme == "https" else 80
    return (
        parsed.scheme == origin.scheme
        and (parsed.hostname or "").lower() == (origin.hostname or "").lower()
        and actual_port == expected_port
    )


def fetch_url(url: str) -> tuple[int, str, str, str | None]:
    """返回 (status, final_url, body, error)。错误返回 status=0 或 HTTP 状态。"""
    request = urllib.request.Request(
        url,
        headers={"User-Agent": "AtlasSiteCrawler/1.0 (+local only)"},
    )
    try:
        with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT) as response:
            status = int(getattr(response, "status", 200) or 200)
            final_url = response.geturl()
            charset = response.headers.get_content_charset() or "utf-8"
            body = response.read().decode(charset, errors="replace")
            return status, final_url, body, None
    except urllib.error.HTTPError as exc:
        try:
            body = exc.read().decode("utf-8", errors="replace")
        except Exception:
            body = ""
        return int(exc.code), exc.geturl() or url, body, f"HTTP {exc.code} {exc.reason}"
    except Exception as exc:
        return 0, url, "", f"{type(exc).__name__}: {exc}"


def crawl(entry: str) -> tuple[list[dict], list[dict]]:
    entry = canonical_url(entry)
    origin = urllib.parse.urlsplit(entry)
    queue: deque[str] = deque([entry])
    seen: set[str] = {entry}
    pages_by_url: OrderedDict[str, dict] = OrderedDict()
    broken_by_url: OrderedDict[str, dict] = OrderedDict()

    while queue:
        url = queue.popleft()
        status, final_url, body, error = fetch_url(url)
        canonical_final = canonical_url(final_url)

        if status != 200:
            broken = broken_by_url.setdefault(
                canonical_final,
                {
                    "url": canonical_final,
                    "status": status,
                    "error": error or f"HTTP {status}",
                    "sources": [],
                },
            )
            if url != canonical_final:
                broken["requested_url"] = url
            continue

        content_type = ""
        # 只解析 HTML 页面；其它同源资源（即使被链接）不进入页面列表。
        parser = LinkExtractor()
        parser.feed(body)
        parser.close()
        title = parser.title or "(untitled)"

        if canonical_final in pages_by_url:
            continue

        outlinks: list[str] = []
        raw_seen_for_page: set[str] = set()
        for href in parser.links:
            resolved = urllib.parse.urljoin(url, href).strip()
            if not resolved:
                continue
            resolved_no_fragment = urllib.parse.urlsplit(resolved)._replace(fragment="").geturl()
            if not same_origin(resolved_no_fragment, origin):
                # 只记录但不抓取任何外网/非 http 链接。
                if urllib.parse.urlsplit(resolved_no_fragment).scheme in ("http", "https"):
                    outlinks.append(resolved_no_fragment)
                continue
            canonical = canonical_url(resolved_no_fragment)
            if canonical not in raw_seen_for_page:
                raw_seen_for_page.add(canonical)
                outlinks.append(canonical)
            if canonical not in seen:
                seen.add(canonical)
                queue.append(canonical)

        page = {
            "url": canonical_final,
            "path": urllib.parse.urlsplit(canonical_final).path or "/",
            "title": title,
            "status": status,
            "links": outlinks,
        }
        pages_by_url[canonical_final] = page

    # 将坏链来源回填到页面出链之外，并去重。
    pages = list(pages_by_url.values())
    pages.sort(key=lambda item: item["path"])
    broken_links = list(broken_by_url.values())
    broken_links.sort(key=lambda item: item["url"])

    for url, broken in broken_by_url.items():
        for page in pages:
            if url in page["links"]:
                source = page["url"]
                if source not in broken["sources"]:
                    broken["sources"].append(source)

    return pages, broken_links


def find_chrome() -> str:
    env_bin = os_environ_chrome_bin()
    if env_bin:
        return env_bin
    for name in ("google-chrome", "google-chrome-stable", "chromium", "chromium-browser"):
        found = shutil.which(name)
        if found:
            return found
    raise RuntimeError("未找到 Chrome/Chromium，无法截图；请设置 CHROME_BIN 环境变量")


def os_environ_chrome_bin() -> str | None:
    import os

    value = os.environ.get("CHROME_BIN", "").strip()
    if value and Path(value).exists():
        return value
    return None


def screenshot_filename(page_url: str) -> str:
    path = urllib.parse.urlsplit(page_url).path.strip("/")
    slug = path.replace("/", "__") or "root"
    return f"{slug}.png"


def screenshot_page(chrome: str, url: str, destination: Path) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    profile_dir = tempfile.mkdtemp(prefix="atlas-chrome-profile-")
    command = [
        chrome,
        "--headless",
        "--disable-gpu",
        "--no-sandbox",
        "--hide-scrollbars",
        "--force-device-scale-factor=1",
        "--window-size=1280,900",
        "--virtual-time-budget=1000",
        "--no-first-run",
        "--no-default-browser-check",
        f"--user-data-dir={profile_dir}",
        f"--screenshot={destination}",
        url,
    ]
    result = subprocess.run(command, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=SCREENSHOT_TIMEOUT)
    shutil.rmtree(profile_dir, ignore_errors=True)
    if result.returncode != 0:
        raise RuntimeError(f"Chrome 截图失败({result.returncode}): {url}")
    if not destination.exists() or destination.stat().st_size == 0:
        raise RuntimeError(f"Chrome 未生成截图文件: {url}")


def make_screenshots(pages: list[dict]) -> list[str]:
    if SCREENSHOTS_DIR.exists():
        shutil.rmtree(SCREENSHOTS_DIR)
    SCREENSHOTS_DIR.mkdir(parents=True)
    chrome = find_chrome()
    generated: list[str] = []
    for page in pages:
        url = page["url"]
        relative = f"screenshots/{screenshot_filename(url)}"
        destination = ROOT / relative
        last_error: Exception | None = None
        for attempt in range(2):
            try:
                screenshot_page(chrome, url, destination)
                if destination.read_bytes()[:8] != b"\x89PNG\r\n\x1a\n":
                    raise RuntimeError("生成的文件不是有效 PNG")
                break
            except Exception as exc:
                last_error = exc
                time.sleep(0.3)
        else:
            raise RuntimeError(f"{url} 截图重试后仍失败: {last_error}")
        generated.append(relative)
        print(f"  [shot] {relative}  ({destination.stat().st_size} bytes)")
    return generated


def build_tree(pages: list[dict], broken_links: list[dict]) -> dict:
    """把页面路径构造成嵌套树，便于渲染可视化站点地图。"""
    root: dict = {}
    for page in pages:
        parts = [part for part in page["path"].split("/") if part]
        node = root
        for part in parts:
            node = node.setdefault(part, {})
        node["__page__"] = page
    for broken in broken_links:
        path = urllib.parse.urlsplit(broken["url"]).path
        parts = [part for part in path.split("/") if part]
        node = root
        for part in parts:
            node = node.setdefault(part, {})
        node.setdefault("__broken__", broken)
    return root


def render_tree(node: dict) -> str:
    entries = sorted(node.keys(), key=lambda k: (k.startswith("__"), k != "index.html", k))
    parts: list[str] = []
    page = node.get("__page__")
    broken = node.get("__broken__")
    if page:
        title = html.escape(page["title"])
        url = html.escape(page["url"])
        screenshot = html.escape(page.get("screenshot", ""), quote=True)
        img = f'<img src="{screenshot}" alt="{title} 截图" loading="lazy">' if screenshot else ""
        parts.append(
            f'<li class="page"><a href="{url}">{html.escape(page["path"])}</a>'
            f'<span class="muted"> — {title}</span> <span class="status ok">{page["status"]}</span>'
            f"{img}</li>"
        )
    if broken:
        parts.append(
            f'<li class="broken"><span>{html.escape(broken["url"])}</span>'
            f'<span class="status bad">{broken["status"]}</span>'
            f'<span class="muted">bad link, no screenshot</span></li>'
        )
    children = [key for key in entries if not key.startswith("__")]
    if children:
        items = []
        for key in children:
            items.append(f'<li class="branch"><span class="dir">{html.escape(key)}</span>{render_tree(node[key])}</li>')
        parts.append(f"<ul>{''.join(items)}</ul>")
    return f'<ul class="tree">{"".join(parts)}</ul>' if page or broken or children else ""


def write_json(pages: list[dict], broken_links: list[dict]) -> None:
    payload = {
        "origin": DEFAULT_ENTRY.rsplit("/", 1)[0],
        "entry_url": DEFAULT_ENTRY,
        "generator": "crawl.py",
        "summary": {
            "successful_pages": len(pages),
            "screenshots": sum(1 for page in pages if page.get("screenshot")),
            "broken_links": len(broken_links),
        },
        "pages": pages,
        "broken_links": broken_links,
    }
    SITEMAP_JSON.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def write_html(pages: list[dict], broken_links: list[dict]) -> None:
    tree = build_tree(pages, broken_links)
    tree_html = render_tree(tree)
    page_rows = []
    for page in pages:
        page_rows.append(
            "<li>"
            f'<a href="{html.escape(page["url"], quote=True)}">{html.escape(page["title"])}</a>'
            f'<span class="muted">{html.escape(page["path"])}</span>'
            f'<span class="status ok">{page["status"]}</span>'
            "</li>"
        )
    broken_rows = []
    for broken in broken_links:
        sources = ", ".join(f'<a href="{html.escape(src, quote=True)}">{html.escape(src)}</a>' for src in broken.get("sources", []))
        broken_rows.append(
            "<li>"
            f'<span class="status bad">{broken["status"]}</span> '
            f'<code>{html.escape(broken["url"])}</code>'
            f'<span class="muted">来源: {sources or "未知"}</span>'
            "</li>"
        )
    doc = f"""<!doctype html>
